package io.tornado.persistence;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.math.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class MixTradeSimulationTest{private final Instant now=Instant.parse("2026-08-14T10:00:00Z");@Test void longClosesAtExactTargetAndCannotDoubleClose(){var s=simulation(Direction.UP);assertThat(s.observe(new BigDecimal("100.300000000000"),now.plusSeconds(1))).isTrue();assertThat(s.getStatus()).isEqualTo(MixTradeSimulation.Status.TARGET_HIT);assertThat(s.observe(new BigDecimal("90"),now.plusSeconds(2))).isFalse();assertThat(s.getStatus()).isEqualTo(MixTradeSimulation.Status.TARGET_HIT);}@Test void longAndShortStopsAndShortTargetUseInclusiveThresholds(){var longTrade=simulation(Direction.UP);assertThat(longTrade.observe(new BigDecimal("99.500000000000"),now.plusSeconds(1))).isTrue();assertThat(longTrade.getStatus()).isEqualTo(MixTradeSimulation.Status.STOP_LOSS_HIT);var shortTarget=simulation(Direction.DOWN);assertThat(shortTarget.observe(new BigDecimal("99.700000000000"),now.plusSeconds(1))).isTrue();assertThat(shortTarget.getStatus()).isEqualTo(MixTradeSimulation.Status.TARGET_HIT);var shortStop=simulation(Direction.DOWN);assertThat(shortStop.observe(new BigDecimal("100.500000000000"),now.plusSeconds(1))).isTrue();assertThat(shortStop.getStatus()).isEqualTo(MixTradeSimulation.Status.STOP_LOSS_HIT);}@Test void duplicateIdentitySurvivesBestMixRowReplacement(){Coin coin=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(coin,"id",1L);BestMethodMix oldRow=new BestMethodMix(coin,900,2,1,List.of("A","B"),List.of(1,2),List.of("A","B"),50,30,35,.52),newRow=new BestMethodMix(coin,900,2,1,List.of("A","B"),List.of(1,2),List.of("A","B"),60,40,45,.62);ReflectionTestUtils.setField(oldRow,"id",2L);ReflectionTestUtils.setField(newRow,"id",99L);assertThat(MixTradeSimulation.activeKey(coin,oldRow,Direction.UP)).isEqualTo(MixTradeSimulation.activeKey(coin,newRow,Direction.UP));}private MixTradeSimulation simulation(Direction direction){Coin coin=new Coin("BTC","BTCUSDT");ReflectionTestUtils.setField(coin,"id",1L);BestMethodMix mix=new BestMethodMix(coin,900,2,1,List.of("A","B"),List.of(1,1),List.of("A","B"),50,30,35,.52);ReflectionTestUtils.setField(mix,"id",2L);return new MixTradeSimulation(coin,mix,direction,2,new BigDecimal("100"),new BigDecimal("0.5"),now);}}
